"""Generate final R0 quantitative appendix; does not overwrite historical reports."""
from pathlib import Path
from collections import Counter,defaultdict
import json,random,statistics,math,hashlib
BASE=Path('research/results/r0')
def load(pattern):
    return [r for p in sorted(BASE.glob(pattern)) for r in json.loads(p.read_text()).get('games',[]) if isinstance(r.get('config'),dict)]
def q(xs,p):return sorted(xs)[max(0,math.ceil(len(xs)*p)-1)]
def ci(values):
    rng=random.Random(5901);boots=[statistics.mean(rng.choices(values,k=len(values))) for _ in range(3000)]
    return [q(boots,.025),q(boots,.975)]
def interval(v):return f'{v[0]:.3f}–{v[1]:.3f}'
def stats(rows):
    wins=Counter(r['winner'] for r in rows);lengths=[r['plies'] for r in rows];br=[b for r in rows for b in r['branches']];times=[t*1000 for r in rows for t in r['move_seconds']];seeds=sorted({r['seed'] for r in rows});first=[statistics.mean((r['winner']+1)/2 for r in rows if r['seed']==seed) for seed in seeds]
    return dict(games=len(rows),first_win=wins[1],draw=wins[0],second_win=wins[-1],first_score=statistics.mean(first),first_cluster95=ci(first),plies_p50=statistics.median(lengths),plies_p90=q(lengths,.9),plies_p95=q(lengths,.95),branch_p50=statistics.median(br),branch_p90=q(br,.9),branch_mean=statistics.mean(br),branch_range=[min(br),max(br)],move_ms_p50=statistics.median(times),move_ms_p95=q(times,.95),endings=dict(Counter(r['reason'] for r in rows)),anchor_only_games=sum(r['events'].get('anchor_only_plies',0)>0 for r in rows),captures=sum(r['events'].get('captures',0) for r in rows),multi_piece_collapse_events=sum(r['events'].get('multi_piece_collapses',0) for r in rows),opening_first_actions=len({str(r['trace'][0]) for r in rows}),opening_four_actions=len({str(r['trace'][:4]) for r in rows}))
def skill(rows,strong,weak):
    sub=[r for r in rows if set(r['agents'])=={strong,weak}];w=Counter(r['winner']*(1 if r['agents'][0]==strong else -1) for r in sub);values=[statistics.mean((r['winner']*(1 if r['agents'][0]==strong else -1)+1)/2 for r in sub if r['seed']==seed) for seed in sorted({r['seed'] for r in sub})]
    return dict(wins=w[1],draws=w[0],losses=w[-1],score=statistics.mean(values),cluster95=ci(values))
def main():
    rows=load('*_main*.json');summary={c:stats([r for r in rows if r['config']['candidate']==c]) for c in 'ABC'};strength={c:{a+'/'+b:skill([r for r in rows if r['config']['candidate']==c],a,b) for a,b in [('greedy','random'),('tactical','greedy'),('deep','tactical')]} for c in 'ABC'}
    s=['# Final R0 quantitative appendix','','**Experimentally supported:** behaviors of these agents and configurations only. **Verified:** completed records and targeted/oracle tests. No human fun/depth result or release fairness claim. Exact candidate rules are in [20_R0_FORMAL_CANDIDATES.md](20_R0_FORMAL_CANDIDATES.md).','','## Main protocol','','Three candidates × 32 seeds (0–31) × 7 games = **672 games**, including **288 color-swapped unequal-agent pairs** and 96 single random/random controls. Even seeds use canonical starts; odd seeds share a two-random-legal-ply opening before both paired games. All agents use public state; no random outcome rule. Greedy/tactical/deep have depth caps 1/2/4 and common hard 1,200-node turn ceiling; actual effort varies with completed depths. Iterative deepening accepts only completed roots. Cache stores legal lists, static evaluations and preferred moves, NEVER repetition-sensitive search values. Entries bounded at 4,096 per table; ordering can alter budgeted results. Deeper roots share alpha safely; correctness tested against exhaustive depth-two minimax on 24 sampled states. Alternate evaluator is untuned material/centrality, not a learned or independently rated engine.','','Intervals use percentile bootstrap over 32 matched seed clusters (3,000 resamples, seed 5901); eight or four clusters for smaller diagnostics. Agent pairs and protocols sharing a seed are correlated. Degenerate intervals from all wins/draws do not imply zero true uncertainty. First-player score includes half a draw, pools deliberately different agents and starting-position modes, and is NOT optimal first-player advantage. Raw first-action/four-ply counts concern actions after the shared prefix, not distinct strategic plans.','','|Candidate|N|First / draw / second|First score [95% cluster]|Length p50 / p90 / p95|Branch p50 / p90 / mean|Endings|','|---|---:|---|---|---|---|---|']
    for c,z in summary.items():s.append(f"|{c}|{z['games']}|{z['first_win']} / {z['draw']} / {z['second_win']}|{z['first_score']:.3f} [{interval(z['first_cluster95'])}]|{z['plies_p50']:g} / {z['plies_p90']} / {z['plies_p95']}|{z['branch_p50']:g} / {z['branch_p90']} / {z['branch_mean']:.1f}|{z['endings']}|")
    s+=['','## Skill differentiation','','|Candidate|Stronger / weaker|W / D / L|Score [paired cluster 95%]|','|---|---|---|---|']
    for c in 'ABC':
        for pair,z in strength[c].items():s.append(f"|{c}|{pair}|{z['wins']} / {z['draws']} / {z['losses']}|{z['score']:.3f} [{interval(z['cluster95'])}]|")
    s+=['','## Search behavior, interaction and opening counts','','|Candidate|Deep completed depth counts|Move ms p50 / p95, all agents|Captures / multi-piece collapses|Distinct first / four-action prefixes|Anchor-only reached|','|---|---|---|---|---|---|']
    for c in 'ABC':
        rs=[r for r in rows if r['config']['candidate']==c];d=Counter(st['depth'] for r in rs for i,st in enumerate(r['search']) if r['agents'][i%2]=='deep');z=summary[c]
        s.append(f"|{c}|{dict(sorted(d.items()))}|{z['move_ms_p50']:.2f} / {z['move_ms_p95']:.2f}|{z['captures']} / {z['multi_piece_collapse_events']}|{z['opening_first_actions']} / {z['opening_four_actions']}|{z['anchor_only_games']}|")
    s+=['','Timing includes concurrent runs on a Linux/Python 3.12 environment with four CPU-equivalents and 32 GiB cgroup RAM limit. Main process max RSS includes retained results and interpreter, not just search heap: see per-file metadata (A 38,928 KiB; B 52,028 KiB; C 18,624 KiB in delivered run). Separate cache-on/off cold-position timing and traced-allocation experiments are in bench.json. Tracing costs are excluded from benchmark timing samples. No Windows/phone or full-world inference follows.','','## Controlled board-size sweep','','Same reserves (A 5, B 8 plus starting piece, C no reserves/three runners), canonical start and deep/tactical paired seeds 0–3 at each size. 5x5 uses canonical controls, not the mixed main pool. Only four paired seeds per size: descriptive, not a board-size verdict. A draws 8/8, 5/8 and 4/8 at sizes 5/6/7, so this controlled test does not support a universal larger-is-worse conclusion. C first/second seat outcomes flip with board-fill parity: 5x5 first wins 8/8, 6x6 second wins 7/8, 7x7 first wins 7/8; medians reach 19/30/43 plies. Filling all empties gives last-move parity, but earlier immobilization can change it and the 5x5 root is not solved.','','|Candidate / size|N|First / draw / second|Length median|Mean branch|Deep completed depths|','|---|---|---|---|---|---|']
    controls=load('*_canonical_control.json');sizes=load('*_sizes.json')
    for c in 'ABC':
        for n in (5,6,7):
            rs=[r for r in (controls if n==5 else sizes) if r['config']['candidate']==c and r['config']['size']==n and r['seed']<4];z=stats(rs);d=Counter(st['depth'] for r in rs for i,st in enumerate(r['search']) if r['agents'][i%2]=='deep')
            s.append(f"|{c}/{n}|{len(rs)}|{z['first_win']} / {z['draw']} / {z['second_win']}|{z['plies_p50']:g}|{z['branch_mean']:.1f}|{dict(sorted(d.items()))}|")
    s+=['','## Exploratory A ablations','','All canonical deep/tactical pairs, seeds 0–7, 16 games/configuration. These controls were exploratory after main observations. Compare to the matching canonical control, not the random/greedy-enriched main total.','','|Config|W / draw / second|Endings|','|---|---|---|']
    for name in ['A5',*sorted({r['config']['name'] for r in load('A_ablations.json')})]:
        rs=[r for r in (controls if name=='A5' else load('A_ablations.json')) if r['config']['name']==name];z=stats(rs);s.append(f"|{name}|{z['first_win']} / {z['draw']} / {z['second_win']}|{z['endings']}|")
    s+=['','## Compute and evaluator sensitivity','','|Condition|Candidate|Strong W / D / L|Score [paired 95%]|','|---|---|---|---|']
    for filename,strong,weak in [('strength6000.json','deep6','deep'),('profiles.json','deep','tactical')]:
        extra=load(filename)
        for c in sorted({r['config']['candidate'] for r in extra}):
            z=skill([r for r in extra if r['config']['candidate']==c],strong,weak);s.append(f"|{filename}|{c}|{z['wins']} / {z['draws']} / {z['losses']}|{z['score']:.3f} [{interval(z['cluster95'])}]|")
    s+=['','The 6,000-node agent has depth cap six; this is a disclosed larger-compute comparison, not an equal-effort depth experiment. Material evaluator comparisons use canonical even seeds 0–14 for A/C and 0–6 for B; compare to matching main subsets, not aggregate rates. Neither profile is trained/calibrated or a human skill model. Material evaluation omits the B road/C race features, so it is a feature ablation, not an independent expert engine.','','## Old draw classification and exact endgames','','All prior 240 baseline, 96 connectivity and 392 continuation records reproduced, excluding elapsed timing. Previous seven draw totals match exactly. Only **10 of 225** prior continuation draws reached two anchors with exhausted reserves. Pressure7 had 26 move-limit draws and 17 repetitions, but zero bare-anchor cases; therefore bare-anchor deadlock cannot explain its observed decline. Pressure6 had 17 zero-capture games versus 4 for pressure5. Old pressure7 deep agent completed depth two on 636/782 turns versus 85/552 for pressure5. Density, interaction and search coverage differ; size/reserves were confounded previously. All old limit draws had exhausted reserves. Remaining non-bare-anchor traps are NOT proved unavoidable. Raw per-game diagnostics are in prior_draw_diagnosis.json.','','Exact A fresh-history anchor-only retrograde tablebases: 1,200 / 2,520 / 4,704 states on sizes 5/6/7; zero drawn states, maximum attractor layers 14/18/22. Independent coordinate-oracle Bellman verification covers all 1,200 5x5 entries. Existing repetition/remaining 120-ply clock can override fresh-history conclusions. No main A game reached the bare-anchor class: this mathematical repair is real, but does not by itself validate the full-game draw reduction.','','C has a monotone bound n²−6 moves and cannot repeat; 5x5 root remains UNKNOWN after 250,000 proof-search nodes (not a draw). Reduced 3x3 root is a proved first-player win, 4x4 a proved second-player win under this reference. Their outcomes do not solve 5x5. Initially occupied home cells never become empty because of wakes; at most n−3 entry gaps remain, so two-delivery is impossible on the reduced 3/4 boards. Those small solutions are immobilization outcomes. B declares a draw when both sides lack n total potential pieces, which preempts later immobilization contests; this is an explicit adjudication choice, not a general solved endgame.','','No full-board dominant opening, calibrated comeback rate, human strategic diversity, enjoyment or qualitative depth is established. Completed-depth changes and deterministic action divergence are not proof of chess-level depth.','','## Weighted framework and sensitivity','','Criteria weights: simplicity 12, tactics 10, position 14, skill separation 12, draw behavior 12, diversity 8, endgame quality 8, AI feasibility 8, visual readability 6, originality 5, implementation risk 5. The unknown experiential criteria sum to 51 weight. Unknown criteria range 1–5, not disguised as measured scores. Designer provisional simplicity/AI/risk: A 4/4/4, B 3/2/3, C 4/4/4; these are hypotheses. Observed-skill proxy = 1+8·max(0, deep score−0.5), capped at 5; draw proxy = 1+4·(1−draw fraction). They are declared preference transforms, not depth metrics. Proxies use the mixed main sample and should not overrule canonical evidence.','','Default midpoint totals and ranges below use unknown midpoint 3 versus extremes 1/5. Draw-heavy shifts eight points from position to draws; skill-heavy shifts eight points from position to skill. Overlapping ranges and ranking changes prohibit a robust winner claim. A final human prototype decision cannot be manufactured from midpoint scores.','','|Weights|A midpoint [range]|B midpoint [range]|C midpoint [range]|Midpoint lead|','|---|---|---|---|---|']
    weights={'default':[12,10,14,12,12,8,8,8,6,5,5],'draw_heavy':[12,10,6,12,20,8,8,8,6,5,5],'skill_heavy':[12,10,6,20,12,8,8,8,6,5,5]};weighted={}
    for label,w in weights.items():
        scores={}
        for c in 'ABC':
            designer={'A':(4,4,4),'B':(3,2,3),'C':(4,4,4)}[c];v=[designer[0],None,None,min(5,1+8*max(0,strength[c]['deep/tactical']['score']-.5)),1+4*(1-summary[c]['draw']/summary[c]['games']),None,None,designer[1],None,None,designer[2]]
            calc=lambda unknown:sum(ww*(unknown if vv is None else vv) for ww,vv in zip(w,v))/5
            scores[c]=dict(midpoint=calc(3),low=calc(1),high=calc(5))
        weighted[label]=scores;fmt=lambda c:f"{scores[c]['midpoint']:.1f} [{scores[c]['low']:.1f}–{scores[c]['high']:.1f}]";s.append('|'+label+'|'+ '|'.join(fmt(c) for c in 'ABC')+'|'+max(scores,key=lambda c:scores[c]['midpoint'])+'|')
    s+=['','**Decision: RESEARCH STOP for production and rules freeze.** No winner. A is the best narrowly scoped diagnostic lead because it retains identity, repairs a proved endgame defect and shows some search separation. Its default canonical deep/tactical control draws 14/16; higher-compute comparisons still draw 8/16. B/C are rejected for advancement under current evidence, not proved devoid of interesting play. The smallest next task is a proof/strong-search analysis of one archived first-repetition A canonical position, then a tightly bounded human teach-back/replay session if a defensible alternative is found. Do not expand corporate production to avoid this gate.','','## Reproduce','','Use `python -m research.experiments.r0.run --candidate A --seeds 32` (repeat B/C); `--sizes --seeds 4` for each candidate. Commands and diagnostics are listed in r0/README.md. Run writes only owned R0 outputs; use --output-dir for isolated reruns. Historical files remain unchanged. `report.py` regenerates this appendix plus summary/weights JSON; `audit.py` checks every recorded transition with the independent oracle, terminal results and budget ceilings.']
    Path('research/21_R0_RESULTS.md').write_text('\n'.join(s)+'\n')
    experiments=load('*.json');identities={json.dumps([r['config'],r['agents'],r['seed'],r['opening'],r['profile']],sort_keys=True) for r in experiments}
    (BASE/'summary.json').write_text(json.dumps(dict(main=summary,strength=strength,weighted=weighted,recorded_executions=len(experiments),distinct_trial_identities=len(identities)),indent=2)+'\n');print('main',len(rows),'all recorded',len(experiments),'distinct trial identities',len(identities))
if __name__=='__main__':main()
